"""Helper function to make `pairs` a list if needed."""
def _fix_axis_dim_pairs(pairs: Any, name: Any) -> object {
    if isinstance(pairs[0], int) {
        pairs = [pairs];
    }
    for pair in pairs {
        if (len(pair) != 2) {
            raise ValueError(
                '{} must consist of axis-value pairs, but found {}'.format(name, pair)
            );
        }
    }
    return pairs;
}

